const collectRowsBeforeQuality=collectReportRows;collectReportRows=function(){const f=reportSelection();if(f.type==='process_quality'){const old=reportFilters.type;reportFilters.type='quality';try{return collectRowsBeforeQuality()}finally{reportFilters.type=old}}if(f.type!=='quality'&&f.type!=='business')return collectRowsBeforeQuality();const oldFactory=state.factory,oldPeriod=$('#period').value,rows=[];try{$('#period').value=f.period;for(const fi of f.factory<0?factories.map((_,i)=>i):[f.factory]){state.factory=fi;rows.push(...qualityRowsForScope(fi,f.period))}}finally{state.factory=oldFactory;$('#period').value=oldPeriod}return rows};
