function workforceMultiChart(title,labels,series,line=false){const width=620,height=205,max=Math.max(100,...series.flatMap(s=>s.values)),x=i=>50+i*(530/Math.max(1,labels.length-1)),y=v=>165-130*v/max;return `<section class="panel workforce-chart"><div class="panelhead"><h2>${escapeHTML(title)}</h2><small>%</small></div><svg class="analytics-svg" viewBox="0 0 ${width} ${height}" role="img" aria-label="${escapeHTML(title)}">${[0,50,100].map(v=>`<line x1="40" x2="598" y1="${y(v)}" y2="${y(v)}" stroke="#ffffff24"/><text x="31" y="${y(v)+4}" text-anchor="end">${v}</text>`).join('')}${series.map((s,j)=>line?`<path d="M${s.values.map((v,i)=>x(i)+','+y(v)).join(' L')}" fill="none" stroke="${palette[j]}" stroke-width="3"/>${s.values.map((v,i)=>`<circle cx="${x(i)}" cy="${y(v)}" r="4" fill="${palette[j]}" ${vizAttrs(title,labels[i]+' · '+s.name,v,'%')}/>`).join('')}`:s.values.map((v,i)=>`<rect x="${66+i*138+j*23}" y="${y(v)}" width="19" height="${165-y(v)}" rx="3" fill="${palette[j]}" ${vizAttrs(title,labels[i]+' · '+s.name,v,'%')}/>`).join('')).join('')}${labels.map((label,i)=>`<text x="${line?x(i):98+i*138}" y="187" text-anchor="middle" font-size="${line?12:11}">${line?escapeHTML(label):`<tspan x="${98+i*138}" y="179">${escapeHTML(label.split(' ')[0].slice(0,15))}</tspan><tspan x="${98+i*138}" y="195">${escapeHTML(label.split(' ').slice(1).join(' ').slice(0,18))}</tspan>`}</text>`).join('')}</svg><div class="workforce-legend">${series.map((s,i)=>`<span><i style="background:${palette[i]}"></i>${escapeHTML(s.name)}</span>`).join('')}</div></section>`}
