function mountWorkforceNetwork(){if(workforceNetworkMap){workforceNetworkMap.remove();workforceNetworkMap=null}const el=$('#workforce-network-map');if(!el||!window.L)return;const fallback=el.innerHTML;try{workforceNetworkMap=L.map(el,{zoomControl:false,scrollWheelZoom:false,minZoom:4,maxZoom:10}).setView([27.5,30.4],4);L.tileLayer('https://{s}.basemaps.cartocdn.com/dark_all/{z}/{x}/{y}{r}.png',{attribution:'© OpenStreetMap © CARTO',maxZoom:19}).addTo(workforceNetworkMap);factories.forEach((f,i)=>{const v=workforceAnalytics(i),value=workforceMapMetric==='Employees'?v.employees:v.billablePercent+'%',icon=L.divIcon({className:'workforce-map-marker',html:`<span>${escapeHTML(value)}</span>`,iconSize:[42,42],iconAnchor:[21,21]});L.marker(coordinates[i],{icon}).addTo(workforceNetworkMap).bindTooltip(f.name+' · '+workforceMapMetric+': '+value).on('click',()=>workforceRosterDialog(i))});workforceNetworkMap.invalidateSize?.()}catch{el.innerHTML=fallback}}
