const areaDataBeforeQualityRename=smartAreaData;smartAreaData=function(id){const d=areaDataBeforeQualityRename(id);if(id!=='Quality')return d;const b=snapshot();return {...d,metric:b.quality+'%',unit:'first-pass quality',target:'Target 98%',detail:'Compliance '+b.compliance+'%',state:b.quality<98?'Review required':'Operating',action:'Review the Quality scorecard, customer feedback and downtime evidence.'}};


const previewBeforeQualityAlignment=previewProfessionalReport;previewProfessionalReport=function(){if(!['quality','business'].includes(reportSelection().type))return previewBeforeQualityAlignment();const rows=filteredReportRows();if(!rows.length)return;const popup=window.open('','_blank');if(!popup){openModal('Preview blocked','Allow popups to preview the Quality PDF.');return}popup.document.write(buildQualityScorecardReport(rows));popup.document.close();popup.focus()};


function staticQualityChart(row,details,unit){const box=document.createElement('div');box.innerHTML=sourceKpiChart(row.measure,details,details[0]?.unit||unit,row.metric_id==='downtime'?'pareto':row.metric_id==='cost'?'waterfall':row.metric_id==='supplier'?'line':'column');box.querySelectorAll('[data-viz-point]').forEach(el=>{try{const point=JSON.parse(el.getAttribute('data-viz-point')),title=document.createElementNS('http://www.w3.org/2000/svg','title');title.textContent=point.label+': '+point.value+' '+point.unit;el.appendChild(title)}catch{}});box.querySelectorAll('*').forEach(el=>{[...el.attributes].forEach(a=>{if(a.name.startsWith('on')||a.name==='tabindex'||a.name==='data-viz-point'||(a.name==='role'&&a.value==='button'))el.removeAttribute(a.name)})});return box.innerHTML}

function processSystemFor(fi=factoryIndex(),line=state.line){const source=recordFor(fi)?.processSystems?.find(s=>s.index===line);if(source)return {...source,source:true};const connected=!!(recordFor(fi)?.batches||recordFor(fi)?.production);return {id:factoryCodes[fi]+'-PROC-L'+(line+1),name:'Line '+(line+1)+' process system',status:connected?'Not supplied':saved.processSystems?.[fi+'-'+line]||'Running',source:false,connected}}
function processSystemControls(){if(state.factory<0){openModal('Choose a process system',factories.map((f,i)=>opButton(escapeHTML(f.name),`state.factory=${i};render();processSystemControls()`)).join(''));return}const system=processSystemFor(),batches=scopedBatches();openModal(escapeHTML(system.name),`<div class="scope-label">${escapeHTML(scopeName())} · ${escapeHTML(system.id)}</div><div class="metric-reading">${escapeHTML(system.status)}</div><p>${system.source?'Commands require the authorized process-system gateway. The next source snapshot confirms the resulting state.':system.connected?'No mapped process-system target has been supplied. Source batch controls remain available below.':'Demonstration controls affect this process-system state only. Batch states are reviewed separately; no plant equipment is connected.'}</p><div class="actions">${!system.connected||system.source?opButton('Run process system',"setProcessSystem('Running')")+opButton('Stop process system',"setProcessSystem('Stopped')"):''}${opButton('Process alarms','alarmCenter()')}</div><h3>Batch execution</h3><div class="table-scroll"><table><tr><th>Batch</th><th>Stage</th><th>Status</th><th></th></tr>${batches.map(b=>`<tr><td>${b.id}</td><td>${batchStages[b.stage]}</td><td>${b.status}</td><td>${opButton('Execution controls',`batchDetail('${b.id}')`)}</td></tr>`).join('')}</table></div>`);$('#modal').classList.add('wide-modal')}
async function setProcessSystem(status){if(state.factory<0||!['Running','Stopped'].includes(status))return;const s=processSystemFor();if(s.source)return requestOperationsCommand(factoryIndex(),'processSystem',s.id,status);if(s.connected){openModal('Process target not configured','Supply the process-system identity and status from the factory gateway before issuing system commands.');return}saved.processSystems??={};saved.processSystems[factoryIndex()+'-'+state.line]=status;eventLog(s.id+' '+status+' in demonstration','Process');render();processSystemControls()}

render();
